      "codingOriginal": "Ignoring; Third-Party Intermediaries",
      "example": "(a) Mohamed Dheere, former Governor of Middle Shabelle, with its capital in Jowhar, received a quantity of AK-47 assault rifles and ammunition and eight 4x4 vehicles to be used as technicals;\n\n22 November 2006, S/2006/913",
      "excerptId": "2bf036feb7c68a44",
      "reports": [
        "S/2006/913"
      ],
      "reportYear": 2006,
      "sourceFile": "ep 8.2.docx",
