      "codingOriginal": "Ignoring; Third-Party Intermediaries",
      "example": "• 27 July 2007 the Ministry of Finance to pay $120,000 for military uniforms, and 14,800,000,000 Somali shillings (So. Sh.) for other defence-related items, including the provisions of rations for the month of August (see annex VI).\n\n24 April 2008, S/2008/274",
