      "codingOriginal": "Ignoring; Third-Party Intermediaries, Smuggling, PMC",
      "example": "170. Between April 2009 and early 2011, the Hong Kong-based Southern Ace operated in southern Mudug region, in collaboration with two local partners, GalSom and Iidan Fishing Company. During that period, Southern Ace and its local associates recruited and operated a well-equipped, 220-strong militia from the Habar Gidir/Sa’ad/Reer Nim’aale sub-clan, supervised by a dozen Zimbabweans and three Westerners, at an estimated cost of $1 million in salaries and at least $150,000 in arms and ammunition. The result was one of the strongest forces in south Mudug region, with the potential to change the balance of power in the area. 171. Southern Ace also began to explore prospects for arms trafficking and engaged in horticultural experiments aimed at the production of narcotic drugs, including marijuana, cocaine and opium. A detailed case study of Southern Ace activities is contained in annex 6.2.\n\n18 July 2011, S/2011/433",
