      "codingOriginal": "Violation; Black Knights",
      "example": "(c) Support to non-Somali armed groups engaged in acts of destabilization or terrorism in violation of resolution 1907 (2009);\n\n18 July 2011, S/2011/433",
      "excerptId": "5363a7ee3b5f92ff",
