      "codingOriginal": "Ignoring; Black Knights",
      "example": "94. On 7 July 2012, one month after joining AMISOM, KDF resumed unauthorized air strikes in Somalia on Jungal village, 30 kilometres from Baardheere in Sector 2.51 Recently, in January and February 2013, the spokesman for the Forces, Colonel Cyrus Oguna, confirmed that KDF had conducted more air strikes in the Gedo region to “sustain the pressure against the militants [Al-Shabaab]”.52\n\n12 July 2013, S/2013/413",
      "excerptId": "50391b366d345ed6",
      "reports": [
        "S/2013/413"
      ],
      "reportYear": 2013,
      "sourceFile": "ep 8.4.docx",
