      "codingOriginal": "Ignoring; Black Knights",
      "example": "70. In spite of the Committee’s position, according to a UAE official,32 individuals and entities in the UAE have continued to supply technical advice and financial assistance directly to the Puntland Maritime Police Force, in violation of paragraph 2 of Security Council resolution 1425 (2002)\n\n12 July 2013, S/2013/413",
