      "tactics": [
        "PMC"
      ],
      "codingOriginal": "Ignoring; PMC",
      "example": "4. Despite these credentials, the Monitoring Group has established that Tacforce International, a security company based in Dubai and managed by two ex-military Australian nationals, imported into Somalia in February 2013 a B6-type armoured vehicle in violation of the arms embargo, and with the complicity of Somali officials from the National Intelligence and Security Agency (NISA) and the Ministry of Foreign Affairs (see annexes 6.2, 6.2.c and 6.3.a). At an unknown date, it also imported a certain number of flak jackets and military helmets.\n\n12 July 2013, S/2013/413",
      "excerptId": "db08b821af13242b",
      "reports": [
        "S/2013/413"
      ],
      "reportYear": 2013,
      "sourceFile": "ep 8.4.docx",
      "sourceTable": 1,
      "sourceRow": 46
