      "tactics": [
        "Illicit activities to raise funds"
      ],
      "codingOriginal": "Ignoring; Illicit activities to raise funds",
      "example": "48. The Panel received information that ISIL-Somalia extortion threats forced several businesses to close in Bosaso, Puntland, in June 2023. In one case, ISIL-Somalia reportedly threw a grenade at a shop for not complying with the threat.63\n\n2 October 2023, S/2023/724",
      "excerptId": "47ae8d9c31430092",
      "reports": [
        "S/2023/724"
      ],
      "reportYear": 2023,
