      "codingOriginal": "Violation; Smuggling",
      "example": "Two types of ammunition boxes for 7.62x39 mm and 7.62x54 mm, lot number A 10-18 and T 02-18. The Panel identified that these boxes were part of ammunition delivered to Somalia in February 2022 for Danab special forces\n\n2 October 2023, S/2023/724",
