      "codingOriginal": "Obfuscating; Third-Party Intermediaries, Hiding Beneficial Ownership",
      "example": "68. In May 2024, two individuals58 were identified and apprehended for facilitating Al-Shabaab financial transactions using their bank accounts. 59\n\n28 October 2024, S/2024/748",
